        static PropertyInfo? NamedProperty(Type type, string name, BindingFlags flags)
        {
            try { return type.GetProperty(name, flags, binder: null, returnType: null, types: Type.EmptyTypes, modifiers: null); }
            catch (AmbiguousMatchException)
            {
                // Python takes the derived property even when its return type differs from its base property.
                for (Type? owner = type; owner != null; owner = owner.BaseType)
                {
                    var property = owner.GetProperty(name, flags | BindingFlags.DeclaredOnly, binder: null,
                        returnType: null, types: Type.EmptyTypes, modifiers: null);
                    if (property != null) return property;
                }
                return null;
            }
        }

        public static dynamic? getattr(object? o, string name) =>
            TryGetAttr(o, name, out var v) ? v : throw MissingAttribute(o, name);

        static MissingMemberException MissingAttribute(object? receiver, string name, string? message = null) =>
            PyExceptionState.CreateAttributeError([message ?? (receiver switch
            {
                PyModule module => $"module '{module.__name__}' has no attribute '{name}'",
                Type type => $"type object '{PyTypeName(type)}' has no attribute '{name}'",
                _ => $"'{(receiver == null ? "NoneType" : PyTypeName(receiver.GetType()))}' object has no attribute '{name}'",
            })], name, receiver);
        public static dynamic? getattr(object? o, string name, object? @default) =>
            TryGetOptionalAttr(o, name, out var value) ? value : @default;
        public static bool hasattr(object? o, string name) => TryGetOptionalAttr(o, name, out _);

        static bool TryGetOptionalAttr(object? receiver, string name, out object? value)
        {
            try { return TryGetAttr(receiver, name, out value); }
            catch (MissingMemberException)
            {
                if (receiver != null && TryFallbackAttribute(receiver, name, out value)) return true;
                value = null;
                return false;
            }
        }

